    alreadyAccepted: "Tasdiqlangan",
    alreadyAcceptedCta: "Tasdiqlangan",
    s1Title: "Daromad — taxmin, vaʼda emas",
    s1Body: "Ilovada koʻrsatiladigan kunlik va oylik daromad joriy vazifalar talabi, narxlar va qurilma holatiga asoslangan taxmindir. Haqiqiy daromad tushgan yozuvlar boʻyicha boʻladi, taxmindan past boʻlishi mumkin, ayrim davrlarda esa umuman boʻlmasligi mumkin. Oʻtgan daromad kelajakdagi natijani bildirmaydi.",
    s2Title: "Qurilma unumdorligi oʻzgaradi",
    s2Body: "Vazifalar hajmi bozor talabiga qarab oʻzgaradi; onlayn vaqt, internet, elektr va texnik xizmat unumdorlikka taʼsir qiladi. Platforma qoidalariga koʻra qurilma quvvati foydalanish bilan asta-sekin pasayadi va daromad ham kamayishi mumkin. Telefon quvvat bersa, uning unumdorligi telefon modeli, batareya va operatsion tizim bilan cheklanadi.",
    s3Title: "UVT narxi oʻzgaruvchan",
    s3Body: "UVT — platformaning mukofot tokeni. Uning narxi va likvidligi keskin oʻzgarishi, baʼzan esa savdo qilib boʻlmasligi mumkin. UVT qanday olinishi, chiqarilishi va ishlatilishi platforma eʼlon qilgan qoidalarga bogʻliq.",
    s4Title: "Xarid, pul qaytarish va aksiyalar",
    s4Body: "Qurilma xaridi uchun toʻlov odatda qaytarilmaydi, qurilmani yangilash sahifasidagi qoidalar boʻyicha almashtirish mumkin. Aksiya mukofotlari va sinov mablagʻi har bir aksiya qoidalariga bogʻliq; pul qaytarilsa, tegishli mukofotlar qaytarib olinishi mumkin. Buyurtmadan oldin narx, komissiya va xariddan keyingi xizmat maʼlumotlarini tekshiring.",
    s5Title: "Toʻldirish va pul yechish",
    s5Body: "Toʻldirish yoki yechishdan oldin tarmoq va manzilni tekshiring; notoʻgʻri tarmoq yoki manzilga yuborilgan aktivlarni qaytarib boʻlmasligi mumkin. Zanjirdagi oʻtkazmalar tasdiqlangach bekor qilinmaydi. Tarmoq komissiyasi va tushish vaqti tarmoq holatiga bogʻliq va sahifada koʻrsatiladi. Pul yechish xavfsizlik tekshiruvini talab qilishi mumkin, bajarilish vaqti soʻrov holatida koʻrinadi.",
    s6Title: "Taklif va jamoa mukofotlari",
    s6Body: "Taklif va jamoa mukofotlari taklif qilingan foydalanuvchilarning haqiqiy faolligi va amaldagi qoidalarga bogʻliq. Qoidalar oʻzgarishi mumkin, mukofotlarning davom etishi vaʼda qilinmaydi. Soxta akkauntlar, ommaviy roʻyxatdan oʻtish yoki spam orqali olingan mukofotlar bekor qilinadi va akkaunt bloklanishiga olib kelishi mumkin.",
    s7Title: "Akkaunt xavfsizligi va xizmat oʻzgarishlari",
    s7Body: "Parol, tasdiqlash kodlari va toʻlov PIN-kodini ehtiyot qiling — platforma xodimlari ularni hech qachon soʻramaydi. Akkaunt va mablagʻlarni himoya qilish yoki amaldagi qonunlarga rioya qilish uchun platforma ayrim funksiyalar yoki operatsiyalarni toʻxtatishi mumkin. Xizmat texnik ishlar, tarmoq muammolari yoki fors-major sababli uzilishi mumkin; funksiya va qoidalar oʻzgarishi ilovada eʼlon qilinadi.",
    scrollHint: "Tasdiqlashdan oldin barcha boʻlimlarni oxirigacha oʻqing.",
